	}

	return response.json();
}

/**
 * Create or update a triage record
 * AC: @interactive-triage-ui ac-3
 */
export async function createTriageRecord(data: {
	inbox_ref: string;
	action: string;
	reasoning: string;
	decided_by?: string;
