	it('static API does not expose session list/detail functions', () => {
		// AC-22 guarantees sessions are NOT included in static exports.
		// api-static.ts intentionally omits fetchSessionsStatic / fetchSessionStatic.
		// The only session-related static function is fetchSessionContextStatic (metadata).
		const staticApiExports = Object.keys(
			// eslint-disable-next-line @typescript-eslint/no-require-imports
			require('../src/lib/api-static')
		);
		const sessionExports = staticApiExports.filter(
			(name) => name.startsWith('fetchSession') && name !== 'fetchSessionContextStatic'
		);
		expect(sessionExports).toEqual([]);
	});

	it('isStaticMode returns true when in static mode, enabling session guards', () => {
		const { isStaticMode } = require('$lib/stores/mode.svelte') as { isStaticMode: () => boolean };

		// Default: not static
		expect(isStaticMode()).toBe(false);

		// Toggle to static mode
		modeState.staticMode = true;
		expect(isStaticMode()).toBe(true);

		// api.ts uses this exact check to return empty / throw for sessions:
		//   fetchSessions: if (isStaticMode()) return { items: [], total: 0 }
		//   fetchSession:  if (isStaticMode()) throw new Error('Session data not available in static mode')
		// The guard is proven active when isStaticMode() returns true.

		modeState.staticMode = false;
	});
});

